twoDimArray[0][1] = 0; 
8 
twoDimArray[0][2] = 9;

9 
twoDimArray[0][3] = 6; 
10 
twoDimArray[1][0] = 2; 
11 
twoDimArray[1][1] = 0; 
12 
twoDimArray[1][2] = 1; 
13 
twoDimArray[1][3] = 1; 
14 
15 
for(int i = 0; i < 2; i++) 
16 
for(int j = 0; j < 4; j++) 
17 
cout << twoDimArray[i][j]; 
18 
19 
cout << endl; 
20 
